"""The rules of deskstats.timeparse, on values of their own."""

import ast
import os
import time
import unittest
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

from deskstats import cli, timeparse as tp

PLUS1 = timezone(timedelta(hours=1))
PLUS530 = timezone(timedelta(hours=5, minutes=30))


class Offsets(unittest.TestCase):
    def test_offset(self):
        self.assertEqual(tp.parse_offset("+05:30"), PLUS530)
        self.assertEqual(tp.parse_offset("-00:30").utcoffset(None), timedelta(minutes=-30))
        self.assertIsNone(tp.parse_offset("+01:00").tzname(None) and None)
        for bad in ("+0100", "+1:00", " +01:00", "+01:00\n", "", "+24:00", "+99:99"):
            with self.assertRaises(ValueError, msg=bad):
                tp.parse_offset(bad)


class Instants(unittest.TestCase):
    def test_naive_gets_zone(self):
        self.assertEqual(tp.parse_instant(" 2026-03-02T09:15:02 ", tp.UTC), datetime(2026, 3, 2, 9, 15, 2, tzinfo=tp.UTC))
        self.assertEqual(tp.parse_instant("2026-03-02T09:15:02", PLUS1).utcoffset(), timedelta(hours=1))

    def test_offset_kept(self):
        t = tp.parse_instant("20260302T101502.5+0530", PLUS1)
        self.assertEqual(t.utcoffset(), timedelta(hours=5, minutes=30))
        self.assertEqual(t.microsecond, 500000)

    def test_layouts(self):
        layouts = ("%Y-%m-%d %H:%M", "%d.%m.%Y %H:%M")
        self.assertEqual(tp.parse_instant("2026-3-2 9:05", PLUS1, layouts), datetime(2026, 3, 2, 9, 5, tzinfo=PLUS1))
        self.assertEqual(tp.parse_instant("2.3.2026 9:05", PLUS1, layouts), datetime(2026, 3, 2, 9, 5, tzinfo=PLUS1))
        with self.assertRaises(ValueError):
            tp.parse_instant("2.3.2026 9:05", PLUS1)
        with self.assertRaises(ValueError):
            tp.parse_instant("", PLUS1, layouts)

    def test_zone_names_do_not_depend_on_machine(self):
        old = os.environ.get("TZ")
        try:
            os.environ["TZ"] = "America/New_York"
            time.tzset()
            with self.assertRaises(ValueError):
                tp.parse_instant("2026-03-02 09:05 EST", tp.UTC, ("%Y-%m-%d %H:%M %Z",))
            t = tp.parse_instant("2026-03-02 09:05 gmt", tp.UTC, ("%Y-%m-%d %H:%M %Z",))
            self.assertEqual(t, datetime(2026, 3, 2, 9, 5, tzinfo=tp.UTC))
        finally:
            if old is None:
                os.environ.pop("TZ", None)
            else:
                os.environ["TZ"] = old
            time.tzset()


