class Rules(unittest.TestCase):
    def test_public_names(self):
        public = sorted(n for n in vars(tp) if not n.startswith("_") and n not in ("date", "datetime", "time", "timedelta", "timezone", "tzinfo", "re", "itertools"))
        self.assertEqual(public, sorted(["UTC", "SECONDS", "MILLIS", "TRUNCATE", "NEAREST_EVEN", "YMD", "DMY", "MDY",
                                         "parse_offset", "parse_instant", "from_epoch", "parse_day", "at_clock", "day_start"]))

    def test_no_building_outside(self):
        banned_calls = {"strptime", "fromisoformat", "fromtimestamp", "utcfromtimestamp", "fromordinal", "fromisocalendar",
                        "combine", "timestamp", "datetime", "date", "time", "timezone"}
        banned_imports = {"time", "calendar", "email.utils"}
        for path in Path(tp.__file__).parent.glob("*.py"):
            if path.name == "timeparse.py":
                continue
            tree = ast.parse(path.read_text(encoding="utf-8"))
            for node in ast.walk(tree):
                if isinstance(node, ast.Call):
                    f = node.func
                    name = f.attr if isinstance(f, ast.Attribute) else getattr(f, "id", None)
                    self.assertNotIn(name, banned_calls, path.name)
                    if name == "replace":
                        self.assertFalse({k.arg for k in node.keywords} & {"year", "month", "day", "hour", "minute", "second", "microsecond", "tzinfo", "fold"}, path.name)
                if isinstance(node, ast.Import):
                    self.assertFalse({a.name for a in node.names} & banned_imports, path.name)
                if isinstance(node, ast.ImportFrom):
                    self.assertNotIn(node.module, banned_imports, path.name)

    def test_timeparse_imports_nothing_from_deskstats(self):
        tree = ast.parse(Path(tp.__file__).read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom):
                self.assertFalse((node.module or "").startswith("deskstats"))

    def test_window_bounds(self):
        class S:
            tz = PLUS530
        w = cli.window(S, date(2026, 3, 2), date.max)
        self.assertEqual(w.since, datetime(2026, 3, 2, tzinfo=PLUS530))
        self.assertEqual(w.until, datetime(9999, 12, 31, 23, 59, 59, tzinfo=PLUS530))


